     1	// Test harness: spawns `node server.mjs` as a child process and talks to it over raw HTTP.
     2	import { spawn } from 'node:child_process';
     3	import { request as httpRequest } from 'node:http';
     4	import { connect } from 'node:net';
     5	import { mkdtemp, rm } from 'node:fs/promises';
     6	import { tmpdir } from 'node:os';
     7	import { join } from 'node:path';
     8	import { fileURLToPath } from 'node:url';
     9	
    10	export const SERVER_PATH = fileURLToPath(new URL('../../server.mjs', import.meta.url));
    11	export const JSON_TYPE = 'application/json; charset=utf-8';
    12	const START_TIMEOUT_MS = 5000;
    13	const EXIT_TIMEOUT_MS = 5000;
    14	
    15	/** Creates a fresh temp directory; remove it with removeDir. */
    16	export function makeTempDir() {
    17	  return mkdtemp(join(tmpdir(), 'room-bookings-test-'));
    18	}
    19	
    20	export function removeDir(dir) {
    21	  return rm(dir, { recursive: true, force: true });
    22	}
    23	
    24	/**
    25	 * Builds the child env from the parent env without PORT, DATA_FILE and node:test variables,
    26	 * then applies `env`. A value of `undefined` in `env` leaves the variable unset.
    27	 */
    28	function buildEnv(env) {
    29	  const base = { ...process.env };
    30	  for (const key of ['PORT', 'DATA_FILE', 'NODE_TEST_CONTEXT', 'NODE_OPTIONS']) delete base[key];
    31	  const merged = { ...base, ...env };
    32	  return Object.fromEntries(Object.entries(merged).filter(([, value]) => value !== undefined));
    33	}
    34	
    35	function spawnServer({ env = {}, cwd }) {
    36	  if (!cwd) throw new Error('spawnServer needs a cwd (use a temp dir)');
    37	  const child = spawn(process.execPath, [SERVER_PATH], { cwd, env: buildEnv(env), stdio: ['ignore', 'pipe', 'pipe'] });
    38	  const output = { stdout: '', stderr: '' };
    39	  child.stdout.setEncoding('utf8').on('data', (chunk) => { output.stdout += chunk; });
    40	  child.stderr.setEncoding('utf8').on('data', (chunk) => { output.stderr += chunk; });
    41	  const closed = new Promise((resolve) => child.on('close', (code, signal) => resolve({ code, signal })));
    42	  return { child, output, closed };
    43	}
    44	
    45	function withTimeout(promise, ms, what) {
    46	  let timer;
    47	  const timeout = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`timeout: ${what}`)), ms); });
    48	  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
    49	}
    50	
    51	/**
    52	 * Runs the server and waits for it to exit (for startup-failure tests).
    53	 * Resolves { code, signal, stdout, stderr }. Fails if it does not exit in time.
    54	 */
    55	export async function runUntilExit({ env = {}, cwd, timeoutMs = EXIT_TIMEOUT_MS } = {}) {
    56	  const { child, output, closed } = spawnServer({ env, cwd });
    57	  try {
    58	    const { code, signal } = await withTimeout(closed, timeoutMs, 'server did not exit');
    59	    return { code, signal, stdout: output.stdout, stderr: output.stderr };
    60	  } finally {
    61	    if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
    62	  }
    63	}
    64	
    65	/**
    66	 * Starts the server and waits for its listening line.
    67	 * Resolves { port, child, output, closed, isRunning(), stop() }. stop() kills it and waits.
    68	 */
    69	export async function startServer({ env = {}, cwd } = {}) {
    70	  const { child, output, closed } = spawnServer({ env: { PORT: '0', ...env }, cwd });
    71	  const listening = new Promise((resolve, reject) => {
    72	    const check = () => {
    73	      const match = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n/.exec(output.stdout);
    74	      if (match) resolve(Number(match[1]));
    75	    };
    76	    child.stdout.on('data', check);
    77	    closed.then(({ code }) => reject(new Error(`server exited (${code}) before listening: ${output.stderr}`)));
    78	  });
    79	  let port;
    80	  try {
    81	    port = await withTimeout(listening, START_TIMEOUT_MS, 'server did not start');
    82	  } catch (error) {
    83	    child.kill('SIGKILL');
    84	    throw error;
    85	  }
    86	  const isRunning = () => child.exitCode === null && child.signalCode === null;
    87	  const stop = async () => {
    88	    if (isRunning()) child.kill('SIGKILL');
    89	    await closed;
    90	  };
    91	  return { port, child, output, closed, isRunning, stop };
    92	}
    93	
    94	/**
    95	 * Sends one HTTP request (no agent, no keep-alive). `path` is sent as-is (no normalisation).
    96	 * `body` may be a string, a Buffer, an array of chunks (sent chunked, no Content-Length) or undefined.
    97	 * Resolves { status, headers, body: Buffer, text, json() }.
    98	 */
    99	export function request(port, { method = 'GET', path = '/', headers = {}, body } = {}) {
   100	  return new Promise((resolve, reject) => {
   101	    // Node's client does not frame bodies of GET/DELETE/OPTIONS by itself; always send a Content-Length.
   102	    const framed = body === undefined || Array.isArray(body) || hasHeader(headers, 'content-length')
   103	      ? headers
   104	      : { ...headers, 'Content-Length': String(Buffer.byteLength(body)) };
   105	    const req = httpRequest({ host: '127.0.0.1', port, method, path, headers: framed, agent: false }, (res) => {
   106	      const chunks = [];
   107	      res.on('data', (chunk) => chunks.push(chunk));
   108	      res.on('error', reject);
   109	      res.on('end', () => {
   110	        const buffer = Buffer.concat(chunks);
   111	        const text = buffer.toString('utf8');
   112	        resolve({ status: res.statusCode, headers: res.headers, body: buffer, text, json: () => JSON.parse(text) });
   113	      });
   114	    });
   115	    req.on('error', reject);
   116	    if (Array.isArray(body)) {
   117	      body.forEach((chunk) => req.write(chunk));
   118	      req.end();
   119	    } else {
   120	      req.end(body);
   121	    }
   122	  });
   123	}
   124	
   125	function hasHeader(headers, name) {
   126	  return Object.keys(headers).some((key) => key.toLowerCase() === name);
   127	}
   128	
   129	/**
   130	 * Shorthand: POST a JSON value (or a raw string/Buffer) to /api/bookings.
   131	 * Content-Type is application/json unless `contentType` is given; an explicit `contentType: undefined` sends none.
   132	 */
   133	export function postBooking(port, value, options = {}) {
   134	  const { raw = false } = options;
   135	  const contentType = Object.hasOwn(options, 'contentType') ? options.contentType : 'application/json';
   136	  const body = raw ? value : JSON.stringify(value);
   137	  const headers = contentType === undefined ? {} : { 'Content-Type': contentType };
   138	  return request(port, { method: 'POST', path: '/api/bookings', headers, body });
   139	}
   140	
   141	/** Writes raw bytes on a TCP socket and resolves the full raw reply text (for non-ASCII targets). */
   142	export function rawRequest(port, bytes) {
   143	  return new Promise((resolve, reject) => {
   144	    const socket = connect(port, '127.0.0.1', () => socket.end(bytes));
   145	    const chunks = [];
   146	    socket.on('data', (chunk) => chunks.push(chunk));
   147	    socket.on('error', reject);
   148	    socket.on('close', () => resolve(Buffer.concat(chunks).toString('utf8')));
   149	  });
   150	}
   151	
   152	/** A valid booking body; override fields as needed. */
   153	export function validBooking(overrides = {}) {
   154	  return { room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00', ...overrides };
   155	}
   156	// Shared assertions, messages and fixtures for the server/API test files.
   157	import { before, after } from 'node:test';
   158	import assert from 'node:assert/strict';
   159	import { makeTempDir, removeDir, startServer, request, validBooking, JSON_TYPE } from './server-harness.mjs';
   160	
   161	/** The booking reply's keys, sorted. */
   162	export const SIX_KEYS = Object.freeze(['date', 'end', 'id', 'room', 'start', 'title']);
   163	export const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
   164	
   165	/** Every error message the spec names, verbatim. */
   166	export const MSG = Object.freeze({
   167	  type: 'content type must be application/json',
   168	  size: 'body too large',
   169	  object: 'body must be a JSON object',
   170	  room: 'room must be one of Aurora, Borealis, Cosmos',
   171	  title: 'title must be 1 to 80 characters',
   172	  date: 'date must be a valid YYYY-MM-DD date',
   173	  start: 'start must be HH:MM',
   174	  end: 'end must be HH:MM',
   175	  order: 'end must be after start',
   176	  bookingNotFound: 'booking not found',
   177	  notFound: 'not found',
   178	  method: 'method not allowed',
   179	  internal: 'internal error',
   180	});
   181	
   182	/** Exact JSON error reply: status, Content-Type and a body with only the `error` key. */
   183	export function assertJsonError(res, status, message) {
   184	  assert.equal(res.status, status);
   185	  assert.equal(res.headers['content-type'], JSON_TYPE);
   186	  assert.deepEqual(res.json(), { error: message });
   187	}
   188	
   189	/** Exact 201 reply: Content-Type, exactly the six keys, numeric id, and `expected` fields. Returns the booking. */
   190	export function assertCreated(res, expected) {
   191	  assert.equal(res.status, 201);
   192	  assert.equal(res.headers['content-type'], JSON_TYPE);
   193	  const body = res.json();
   194	  assert.deepEqual(Object.keys(body).sort(), SIX_KEYS);
   195	  assert.equal(typeof body.id, 'number');
   196	  assert.deepEqual(body, { id: body.id, ...expected });
   197	  return body;
   198	}
   199	
   200	/** GET /api/bookings (optional query string) and return the bookings array, asserting a 200 JSON reply. */
   201	export async function listBookings(port, query = '') {
   202	  const res = await request(port, { path: `/api/bookings${query}` });
   203	  assert.equal(res.status, 200);
   204	  assert.equal(res.headers['content-type'], JSON_TYPE);
   205	  return res.json().bookings;
   206	}
   207	
   208	let dayCounter = 0;
   209	/** A date (2030 onwards) no other test in this process has used. */
   210	export function freshDate() {
   211	  dayCounter += 1;
   212	  return new Date(Date.UTC(2030, 0, 1 + dayCounter)).toISOString().slice(0, 10);
   213	}
   214	
   215	/** A valid booking body on a fresh date. */
   216	export function freshBooking(overrides = {}) {
   217	  return validBooking({ date: freshDate(), ...overrides });
   218	}
   219	
   220	/** A readable, unique-ish test label for a value: invisible characters are shown as \uXXXX escapes. */
   221	export function label(value) {
   222	  if (value === undefined) return '<missing>';
   223	  return JSON.stringify(value).replace(/[^\x20-\x7e]/gu, (ch) => `\\u{${ch.codePointAt(0).toString(16)}}`);
   224	}
   225	
   226	/**
   227	 * Registers before/after hooks in the current describe that start one server
   228	 * (cwd = temp dir, DATA_FILE='data.json') and stop it. Returns a context whose
   229	 * `port`, `server` and `dir` are set once the before hook ran.
   230	 */
   231	export function useServer() {
   232	  const ctx = {};
   233	  before(async () => {
   234	    ctx.dir = await makeTempDir();
   235	    ctx.server = await startServer({ cwd: ctx.dir, env: { DATA_FILE: 'data.json' } });
   236	    ctx.port = ctx.server.port;
   237	  });
   238	  after(async () => {
   239	    if (ctx.server) await ctx.server.stop();
   240	    if (ctx.dir) await removeDir(ctx.dir);
   241	  });
   242	  return ctx;
   243	}
   244	
   245	/** Runs fn(dir) in a fresh temp dir and always removes it. */
   246	export async function withTempDir(fn) {
   247	  const dir = await makeTempDir();
   248	  try {
   249	    return await fn(dir);
   250	  } finally {
   251	    await removeDir(dir);
   252	  }
   253	}
   254	
   255	/** Starts a server with `options`, runs fn(server) and always stops it. */
   256	export async function withServer(options, fn) {
   257	  const server = await startServer(options);
   258	  try {
   259	    return await fn(server);
   260	  } finally {
   261	    await server.stop();
   262	  }
   263	}

  1	// Startup behaviour of server.mjs: PORT, DATA_FILE, listening line, order of checks.
  2	import { test } from 'node:test';
  3	import assert from 'node:assert/strict';
  4	import net from 'node:net';
  5	import { existsSync } from 'node:fs';
  6	import { mkdir, readFile, writeFile } from 'node:fs/promises';
  7	import { join } from 'node:path';
  8	import { fileURLToPath } from 'node:url';
  9	import { runUntilExit, startServer, request, postBooking, validBooking } from './helpers/server-harness.mjs';
 10	import { withTempDir, withServer } from './helpers/api-assert.mjs';
 11	
 12	const REPO_DIR = fileURLToPath(new URL('..', import.meta.url)).replace(/\/$/, '');
 13	const MAX_PORT_ATTEMPTS = 5;
 14	const PORT_3000_SKIP_MESSAGE = 'port 3000 is in use on this machine; default-port test skipped';
 15	
 16	function assertOneStderrLineExit1(result) {
 17	  assert.equal(result.code, 1);
 18	  assert.equal(result.stdout, '');
 19	  assert.match(result.stderr, /^[^\n]+\n$/);
 20	  assert.equal(result.stderr.includes('    at '), false);
 21	}
 22	
 23	function listenOn(port) {
 24	  return new Promise((resolve, reject) => {
 25	    const blocker = net.createServer();
 26	    blocker.once('error', reject);
 27	    blocker.listen(port, '127.0.0.1', () => resolve(blocker));
 28	  });
 29	}
 30	
 31	function closeServer(blocker) {
 32	  return new Promise((resolve) => blocker.close(resolve));
 33	}
 34	
 35	async function freePort() {
 36	  const blocker = await listenOn(0);
 37	  const { port } = blocker.address();
 38	  await closeServer(blocker);
 39	  return port;
 40	}
 41	
 42	async function withBlockedPort(fn) {
 43	  const blocker = await listenOn(0);
 44	  try {
 45	    return await fn(blocker.address().port);
 46	  } finally {
 47	    await closeServer(blocker);
 48	  }
 49	}
 50	
 51	/**
 52	 * Starts the server with PORT='0'+<free port>. A free port can be taken between
 53	 * probing and binding; then the server exits before listening and we retry with
 54	 * a new free port (up to MAX_PORT_ATTEMPTS). Any other failure is rethrown.
 55	 */
 56	async function startOnZeroPrefixedFreePort(dir) {
 57	  let lastError;
 58	  for (let attempt = 1; attempt <= MAX_PORT_ATTEMPTS; attempt += 1) {
 59	    const free = await freePort();
 60	    try {
 61	      const server = await startServer({ env: { PORT: `0${free}` }, cwd: dir });
 62	      return { free, server };
 63	    } catch (error) {
 64	      if (!error.message.startsWith('server exited')) throw error;
 65	      lastError = error;
 66	    }
 67	  }
 68	  throw lastError;
 69	}
 70	
 71	const INVALID_PORTS = ['abc', '-1', '+80', ' 80', '80 ', '65536', '99999', '1e3', '0x50', '8.0', '٣', '１'];
 72	
 73	for (const port of INVALID_PORTS) {
 74	  test(`invalid PORT ${JSON.stringify(port)} writes one stderr line and exits 1`, () => withTempDir(async (dir) => {
 75	    assertOneStderrLineExit1(await runUntilExit({ env: { PORT: port }, cwd: dir }));
 76	  }));
 77	}
 78	
 79	test('PORT is checked before the data file is read', () => withTempDir(async (dir) => {
 80	  await mkdir(join(dir, 'dir'));
 81	  const result = await runUntilExit({ env: { PORT: 'abc', DATA_FILE: 'dir' }, cwd: dir });
 82	  assertOneStderrLineExit1(result);
 83	  assert.notEqual(result.stderr, 'cannot read data file dir\n');
 84	}));
 85	
 86	test('a port that is in use writes one stderr line and exits 1', () => withTempDir((dir) => withBlockedPort(async (port) => {
 87	  assertOneStderrLineExit1(await runUntilExit({ env: { PORT: String(port) }, cwd: dir }));
 88	})));
 89	
 90	test('the data file is read before listening: bad file wins over a port in use', () => withTempDir((dir) => withBlockedPort(async (port) => {
 91	  await mkdir(join(dir, 'dir'));
 92	  const result = await runUntilExit({ env: { PORT: String(port), DATA_FILE: 'dir' }, cwd: dir });
 93	  assert.equal(result.code, 1);
 94	  assert.equal(result.stdout, '');
 95	  assert.equal(result.stderr, 'cannot read data file dir\n');
 96	})));
 97	
 98	test('PORT=0 prints exactly the listening line with the bound port and nothing else', () => withTempDir((dir) => (
 99	  withServer({ env: { PORT: '0' }, cwd: dir }, async ({ port, output }) => {
100	    const line = `listening on http://127.0.0.1:${port}\n`;
101	    assert.equal(output.stdout, line);
102	    const rooms = await request(port, { path: '/api/rooms' });
103	    assert.equal(rooms.status, 200);
104	    await request(port, { path: '/api/bookings' });
105	    assert.equal((await postBooking(port, validBooking())).status, 201);
106	    assert.equal((await request(port, { path: '/nope' })).status, 404);
107	    assert.equal((await postBooking(port, {})).status, 400);
108	    assert.equal(output.stdout, line);
109	  })
110	)));
111	
112	function probePort3000() {
113	  return listenOn(3000).then(closeServer, () => 'busy');
114	}
115	
116	test('unset and empty PORT listen on 3000', (testContext) => withTempDir(async (dir) => {
117	  if (await probePort3000() === 'busy') return testContext.skip(PORT_3000_SKIP_MESSAGE);
118	  for (const port of [undefined, '']) {
119	    await withServer({ env: { PORT: port }, cwd: dir }, ({ output }) => {
120	      assert.equal(output.stdout, 'listening on http://127.0.0.1:3000\n');
121	    });
122	  }
123	  return undefined;
124	}));
125	
126	test('PORT made only of digits with leading zeros is valid (00000 lets the OS pick)', () => withTempDir((dir) => (
127	  withServer({ env: { PORT: '00000' }, cwd: dir }, ({ port, output }) => {
128	    assert.notEqual(port, 0);
129	    assert.equal(output.stdout, `listening on http://127.0.0.1:${port}\n`);
130	  })
131	)));
132	
133	test('PORT with a leading zero binds that port', () => withTempDir(async (dir) => {
134	  const { free, server } = await startOnZeroPrefixedFreePort(dir);
135	  try {
136	    assert.equal(server.port, free);
137	    assert.equal(server.output.stdout, `listening on http://127.0.0.1:${free}\n`);
138	  } finally {
139	    await server.stop();
140	  }
141	}));
142	
143	async function parsedObject(path) {
144	  const value = JSON.parse(await readFile(path, 'utf8'));
145	  assert.equal(typeof value, 'object');
146	  assert.notEqual(value, null);
147	  return value;
148	}
149	
150	for (const dataFile of [undefined, '']) {
151	  test(`DATA_FILE ${dataFile === undefined ? 'unset' : 'empty'} saves to bookings.json in the cwd`, () => withTempDir(async (dir) => {
152	    await withServer({ env: { DATA_FILE: dataFile }, cwd: dir }, async ({ port }) => {
153	      assert.equal((await postBooking(port, validBooking())).status, 201);
154	    });
155	    await parsedObject(join(dir, 'bookings.json'));
156	  }));
157	}
158	
159	test('a relative DATA_FILE resolves against the cwd, not the server folder', () => withTempDir(async (dir) => {
160	  const repoFile = join(REPO_DIR, 'bookings.json');
161	  const repoFileExistedBefore = existsSync(repoFile);
162	  await mkdir(join(dir, 'sub'));
163	  await withServer({ env: { DATA_FILE: 'sub/data.json' }, cwd: dir }, async ({ port }) => {
164	    assert.equal((await postBooking(port, validBooking())).status, 201);
165	  });
166	  await parsedObject(join(dir, 'sub', 'data.json'));
167	  assert.equal(existsSync(join(REPO_DIR, 'sub')), false);
168	  assert.equal(existsSync(repoFile), repoFileExistedBefore);
169	}));
170	
171	test('a missing data file (ENOENT) means no bookings', () => withTempDir(async (dir) => {
172	  await withServer({ env: { DATA_FILE: 'missing.json' }, cwd: dir }, async ({ port }) => {
173	    const reply = await request(port, { path: '/api/bookings' });
174	    assert.equal(reply.status, 200);
175	    assert.deepEqual(reply.json(), { bookings: [] });
176	  });
177	  assert.equal(existsSync(join(dir, 'missing.json')), false);
178	}));
179	
180	test('missing folders on the data path mean no bookings and are never created', () => withTempDir(async (dir) => {
181	  await withServer({ env: { DATA_FILE: 'nofolder/deeper/x.json' }, cwd: dir }, async ({ port }) => {
182	    for (let round = 0; round < 2; round += 1) {
183	      const reply = await request(port, { path: '/api/bookings' });
184	      assert.equal(reply.status, 200);
185	      assert.deepEqual(reply.json(), { bookings: [] });
186	    }
187	  });
188	  assert.equal(existsSync(join(dir, 'nofolder')), false);
189	}));
190	
191	const BAD_CONTENTS = [
192	  ['empty file', ''],
193	  ['not json', 'not json'],
194	  ['truncated object', '{'],
195	  ['null', 'null'],
196	  ['array', '[]'],
197	  ['empty object', '{}'],
198	  ['string', '"x"'],
199	  ['only nextId', '{"nextId":1}'],
200	  ['only bookings', '{"bookings":[]}'],
201	  ['extra key', '{"nextId":1,"bookings":[],"extra":1}'],
202	  ['nextId as string', '{"nextId":"1","bookings":[]}'],
203	  ['unknown room', '{"nextId":2,"bookings":[{"id":1,"room":"Nope","title":"t","date":"2026-11-03","start":"09:00","end":"10:00"}]}'],
204	];
205	
206	const NAME_FORMS = [
207	  ['plain', () => 'data.json'],
208	  ['dot-slash', () => './data.json'],
209	  ['dot-dot segment', () => 'sub/../data.json'],
210	  ['absolute', (dir) => join(dir, 'data.json')],
211	];
212	
213	function assertCannotRead(result, name) {
214	  assert.equal(result.code, 1);
215	  assert.equal(result.stdout, '');
216	  assert.equal(result.stderr, `cannot read data file ${name}\n`);
217	}
218	
219	for (const [formLabel, nameOf] of NAME_FORMS) {
220	  test(`unreadable data file given as ${formLabel} path (a directory) reports the name as given`, () => withTempDir(async (dir) => {
221	    await mkdir(join(dir, 'sub'));
222	    await mkdir(join(dir, 'data.json'));
223	    const name = nameOf(dir);
224	    assertCannotRead(await runUntilExit({ env: { DATA_FILE: name }, cwd: dir }), name);
225	  }));
226	
227	  for (const [label, content] of BAD_CONTENTS) {
228	    test(`data file ${label} given as ${formLabel} path reports the name as given`, () => withTempDir(async (dir) => {
229	      await mkdir(join(dir, 'sub'));
230	      await writeFile(join(dir, 'data.json'), content);
231	      const name = nameOf(dir);
232	      assertCannotRead(await runUntilExit({ env: { DATA_FILE: name }, cwd: dir }), name);
233	    }));
234	  }
235	}
