245	/** Bytes of `value` as JSON padded with spaces inside the object to exactly `size` bytes. */
246	function paddedBody(value, size) {
247	  const json = JSON.stringify(value);
248	  const padding = size - Buffer.byteLength(json);
249	  assert.ok(padding >= 0);
250	  const text = '{' + ' '.repeat(padding) + json.slice(1);
251	  assert.equal(Buffer.byteLength(text), size);
252	  return Buffer.from(text);
253	}
254	
255	/** Body with an ignored "pad" key of U+00E9 (2 bytes each) plus spaces, exactly `size` bytes. */
256	function accentBody(value, size) {
257	  const baseBytes = Buffer.byteLength(JSON.stringify({ ...value, pad: '' }));
258	  const count = Math.floor((size - baseBytes) / 2);
259	  const text = JSON.stringify({ ...value, pad: '\u{e9}'.repeat(count) });
260	  const full = ' '.repeat(size - Buffer.byteLength(text)) + text;
261	  assert.equal(Buffer.byteLength(full), size);
262	  return { buffer: Buffer.from(full), text: full };
263	}
264	
265	function chunked(buffer, chunkSize = 1000) {
266	  const chunks = [];
267	  for (let offset = 0; offset < buffer.length; offset += chunkSize) {
268	    chunks.push(buffer.subarray(offset, offset + chunkSize));
269	  }
270	  return chunks;
271	}
