 23	/** A text node made by `append(string)`. */
 24	export class TextNode {
 25	  constructor(data) { this.data = String(data); }
 26	}
 27	
 28	/** Minimal element: children, textContent, value, type, disabled, listeners. */
 29	export class FakeElement {
 30	  constructor(page, tag, id) {
 31	    this.page = page;
 32	    this.tagName = tag;
 33	    this.id = id;
 34	    this.childNodes = [];
 35	    this.listeners = {};
 36	    this.attrs = { value: '', type: undefined, disabled: false };
 37	  }
 38	  get textContent() {
 39	    return this.childNodes.map((n) => (n instanceof TextNode ? n.data : n.textContent)).join('');
 40	  }
 41	  set textContent(text) {
 42	    this.page.log.push({ id: this.id, prop: 'textContent', value: String(text), bookDisabled: this.page.bookDisabled() });
 43	    this.childNodes = String(text) === '' ? [] : [new TextNode(text)];
 44	  }
 45	  get value() { return this.tagName === 'select' ? this.selectValue() : this.attrs.value; }
 46	  set value(v) {
 47	    this.page.log.push({ id: this.id, prop: 'value', value: String(v), bookDisabled: this.page.bookDisabled() });
 48	    if (this.tagName === 'select') this.selectedValue = String(v);
 49	    else this.attrs = { ...this.attrs, value: String(v) };
 50	  }
 51	  get type() { return this.attrs.type; }
 52	  set type(v) { this.attrs = { ...this.attrs, type: String(v) }; }
 53	  get disabled() { return this.attrs.disabled; }
 54	  set disabled(v) { this.attrs = { ...this.attrs, disabled: Boolean(v) }; }
 55	  selectValue() {
 56	    if (this.selectedValue !== undefined) return this.selectedValue;
 57	    const first = this.childNodes.find((n) => n instanceof FakeElement && n.tagName === 'option');
 58	    return first ? first.value : '';
 59	  }
 60	  append(...nodes) {
 61	    this.childNodes = [...this.childNodes, ...nodes.map((n) => (typeof n === 'string' ? new TextNode(n) : unwrap(n)))];
 62	  }
 63	  replaceChildren(...nodes) {
 64	    this.page.log.push({ id: this.id, prop: 'replaceChildren', value: nodes.length, bookDisabled: this.page.bookDisabled() });
 65	    this.childNodes = nodes.map((n) => (typeof n === 'string' ? new TextNode(n) : unwrap(n)));
 66	  }
 67	  addEventListener(type, handler) {
 68	    this.listeners = { ...this.listeners, [type]: [...(this.listeners[type] ?? []), handler] };
 69	  }
 70	  /** Test side: fires an event; returns { defaultPrevented }. */
 71	  dispatch(type) {
 72	    const state = { defaultPrevented: false };
