228	function closeTag(text, i, root, cur) {
229	  const end = text.indexOf('>', i);
230	  const name = text.slice(i + 2, end < 0 ? text.length : end).trim().toLowerCase();
231	  let next = cur;
232	  for (let n = cur; n && n !== root; n = n.parent) {
233	    if (n.tag === name) { next = n.parent; break; }
234	  }
235	  return { cur: next, i: end < 0 ? text.length : end + 1 };
236	}
