238	function openTag(text, i, cur) {
239	  const m = /^<([a-zA-Z][^\s\/>]*)((?:"[^"]*"|'[^']*'|[^'">])*)>/.exec(text.slice(i));
240	  if (!m) return null;
241	  const tag = m[1].toLowerCase();
242	  const node = { tag, attrs: parseAttrs(m[2]), children: [], parent: cur };
243	  cur.children.push(node);
244	  i += m[0].length;
245	  if (VOID.has(tag)) return { cur, i };
246	  if (!RAW.has(tag)) return { cur: node, i };
247	  const close = new RegExp('</' + tag + '\\s*>', 'i').exec(text.slice(i));
248	  const stop = close ? i + close.index : text.length;
249	  if (stop > i) node.children.push({ text: text.slice(i, stop), parent: node });
250	  return { cur, i: close ? stop + close[0].length : text.length };
251	}
