253	export function parseHtml(text) {
254	  const root = { tag: '#root', attrs: {}, children: [], parent: null };
255	  let cur = root;
256	  let i = 0;
257	  const addText = (t) => { if (t) cur.children.push({ text: t, parent: cur }); };
258	  while (i < text.length) {
259	    const lt = text.indexOf('<', i);
260	    if (lt < 0) { addText(text.slice(i)); break; }
261	    addText(text.slice(i, lt));
262	    i = lt;
263	    if (text.startsWith('<!--', i)) {
264	      const end = text.indexOf('-->', i + 4);
265	      i = end < 0 ? text.length : end + 3;
266	    } else if (text.startsWith('<!', i) || text.startsWith('<?', i)) {
267	      const end = text.indexOf('>', i);
268	      i = end < 0 ? text.length : end + 1;
269	    } else if (text.startsWith('</', i)) {
270	      ({ cur, i } = closeTag(text, i, root, cur));
271	    } else {
272	      const r = openTag(text, i, cur);
273	      if (!r) { addText('<'); i++; } else { cur = r.cur; i = r.i; }
274	    }
275	  }
276	  return root;
277	}
